<template><main class="page"><form class="card" @submit.prevent="submit"><div class="brand">✦ Formly</div><small>CUSTOMER WORKSPACE</small><h1>Welcome back.</h1><p>Sign in to manage forms and view submissions.</p><label>Email<input v-model.trim="email" type="email" required autocomplete="email" /></label><label>Password<input v-model="password" type="password" required autocomplete="current-password" /></label><button :disabled="busy">{{ busy ? 'Signing in…' : 'Sign in →' }}</button><p v-if="error" class="error">{{ error }}</p></form></main></template>
<script>export default {data(){return{email:'',password:'',busy:false,error:''}},methods:{async submit(){this.busy=true;this.error='';try{const response=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:this.email,password:this.password})});if(!response.ok)throw new Error('Invalid email or password');const next=new URLSearchParams(location.search).get('next');location.href=next?.startsWith('/')&&!next.startsWith('//')?next:'/index.html?formId=3'}catch(e){this.error=e.message}finally{this.busy=false}}}};</script>
<style scoped>:global(body){margin:0;font-family:system-ui;background:#f6f5fc;color:#27243d}.page{min-height:100vh;display:grid;place-items:center}.card{width:min(380px,90vw);padding:32px;background:white;border-radius:16px;box-shadow:0 16px 45px #2222}.brand{font-weight:800;color:#6556ef;font-size:22px}small{color:#6656ef;font-weight:800}h1{margin-bottom:4px}p{color:#777;font-size:13px}label{display:block;font-size:13px;margin:18px 0}input{display:block;width:94%;padding:11px;border:1px solid #ddd;border-radius:7px;margin-top:5px}button{background:#6556ef;color:white;border:0;border-radius:8px;padding:12px;width:100%;font-weight:700;cursor:pointer}.error{color:#b33}</style>